#include "heartgcn/model.h"
#include <algorithm>
#include <cmath>
#include <fstream>
#include <iomanip>
#include <limits>
#include <numeric>
#include <queue>
#include <random>
#include <stdexcept>

namespace heartgcn {
static void require(bool c, const char* m) { if (!c) throw std::invalid_argument(m); }
Vector meanSageAggregate(const std::vector<Vector>& n, std::optional<size_t> d) {
  if (n.empty()) { require(d && *d > 0, "empty neighborhood requires dimension"); return Vector(*d, 0); }
  const size_t cols=n.front().size(); require(cols>0,"empty vector"); Vector out(cols);
  for(const auto& v:n){require(v.size()==cols,"neighbor dimensions differ"); for(size_t i=0;i<cols;++i)out[i]+=v[i];}
  for(double& x:out)x/=n.size(); return out;
}
static Vector mv(const Matrix& a,const Vector& x){Vector y(a.size());for(size_t i=0;i<a.size();++i){require(a[i].size()==x.size(),"matrix dimension");y[i]=std::inner_product(a[i].begin(),a[i].end(),x.begin(),0.0);}return y;}
Vector graphSageUpdate(const Vector& s,const std::vector<Vector>& n,const SageParameters& p){auto a=meanSageAggregate(n,s.size()),x=mv(p.selfWeights,s),y=mv(p.neighborWeights,a);require(x.size()==y.size()&&x.size()==p.selfBias.size()&&x.size()==p.neighborBias.size(),"bias dimension");for(size_t i=0;i<x.size();++i){x[i]+=y[i]+p.selfBias[i]+p.neighborBias[i];if(x[i]<0)x[i]*=p.negativeSlope;}return x;}
double weightedLatMse(const Vector& p,const Vector& y,const std::vector<bool>& m){require(!p.empty()&&p.size()==y.size()&&p.size()==m.size(),"loss dimension");double s=0;for(size_t i=0;i<p.size();++i)s+=(m[i]?2.:1.)*(p[i]-y[i])*(p[i]-y[i]);return s/p.size();}
double qrsDuration(const Vector& t){require(!t.empty(),"empty times");auto [a,b]=std::minmax_element(t.begin(),t.end());return *b-*a;}
Loss combinedLoss(const Vector&p,const Vector&y,const std::vector<bool>&m){double a=weightedLatMse(p,y,m),q=std::pow(qrsDuration(p)-qrsDuration(y),2);return{a,q,a+q};}
Matrix anisotropyTensor(const Vector& f,double r){require(!f.empty()&&r>0&&r<=1,"anisotropy input");double norm=std::sqrt(std::inner_product(f.begin(),f.end(),f.begin(),0.0));require(norm>0,"zero fiber");Matrix d(f.size(),Vector(f.size()));for(size_t i=0;i<f.size();++i)for(size_t j=0;j<f.size();++j)d[i][j]=(1-r)*f[i]*f[j]/(norm*norm)+(i==j?r:0);return d;}
double virtualEdgeLength(const Vector&e,const Vector&f,double r){require(e.size()==f.size(),"edge dimension");auto d=anisotropyTensor(f,r);double q=0;for(size_t i=0;i<e.size();++i)for(size_t j=0;j<e.size();++j)q+=e[i]*d[i][j]*e[j];return std::sqrt(q);}
double edgeTravelTime(double l,double s){require(l>=0&&s>=0,"negative travel input");return s==0?std::numeric_limits<double>::infinity():l/s;}
Experiment syntheticWavefront(int nx,int ny,int source,double speed){require(nx>0&&ny>0&&source>=0&&source<nx*ny&&speed>=0,"grid input");Experiment e{nx,ny,source,speed};int n=nx*ny;e.adjacency.resize(n);for(int j=0;j<ny;++j)for(int i=0;i<nx;++i){int u=j*nx+i;e.coordinates.push_back({i,j});if(i+1<nx){int v=u+1,w=0;e.adjacency[u].push_back({v,edgeTravelTime(1,speed)});e.adjacency[v].push_back({u,edgeTravelTime(1,speed)});}if(j+1<ny){int v=u+nx;e.adjacency[u].push_back({v,edgeTravelTime(1,speed)});e.adjacency[v].push_back({u,edgeTravelTime(1,speed)});}}
 e.truth.assign(n,std::numeric_limits<double>::infinity());e.truth[source]=0;using P=std::pair<double,int>;std::priority_queue<P,std::vector<P>,std::greater<P>>q;q.push({0,source});while(!q.empty()){auto[d,u]=q.top();q.pop();if(d!=e.truth[u])continue;for(auto[v,w]:e.adjacency[u])if(d+w<e.truth[v]){e.truth[v]=d+w;q.push({d+w,v});}}return e;}
static Vector solve(Matrix a,Vector b){int n=(int)b.size();for(int k=0;k<n;++k){int p=k;for(int i=k+1;i<n;++i)if(std::abs(a[i][k])>std::abs(a[p][k]))p=i;require(std::abs(a[p][k])>1e-14,"singular harmonic system");std::swap(a[p],a[k]);std::swap(b[p],b[k]);for(int i=k+1;i<n;++i){double f=a[i][k]/a[k][k];for(int j=k;j<n;++j)a[i][j]-=f*a[k][j];b[i]-=f*b[k];}}Vector x(n);for(int i=n-1;i>=0;--i){double s=b[i];for(int j=i+1;j<n;++j)s-=a[i][j]*x[j];x[i]=s/a[i][i];}return x;}
Reconstruction sparseReconstruction(const Experiment&e,double fraction,double noise){require(fraction>=0&&fraction<=1&&noise>=0,"sampling input");int n=e.truth.size(),count=std::min(n,std::max(2,(int)std::lround(fraction*n)));std::mt19937 g(42);std::vector<int> all(n);std::iota(all.begin(),all.end(),0);std::shuffle(all.begin(),all.end(),g);all.resize(count);std::sort(all.begin(),all.end());std::normal_distribution<double> nd(0,noise);Reconstruction r;r.fraction=fraction;r.noise=noise;r.measuredIndices=all;r.estimate.assign(n,0);std::vector<bool> known(n);for(int i:all){known[i]=true;double v=e.truth[i]+(noise==0?0:nd(g));r.measuredValues.push_back(v);r.estimate[i]=v;}std::vector<int> u;for(int i=0;i<n;++i)if(!known[i])u.push_back(i);Matrix a(u.size(),Vector(u.size()));Vector b(u.size());std::vector<int> pos(n,-1);for(size_t i=0;i<u.size();++i)pos[u[i]]=i;for(size_t row=0;row<u.size();++row){int v=u[row];a[row][row]=e.adjacency[v].size();for(auto[w,_]:e.adjacency[v])if(known[w])b[row]+=r.estimate[w];else a[row][pos[w]]-=1;}if(!u.empty()){auto x=solve(a,b);for(size_t i=0;i<u.size();++i)r.estimate[u[i]]=x[i];}for(int i=0;i<n;++i)r.mae+=std::abs(r.estimate[i]-e.truth[i]);r.mae/=n;return r;}
static bool near(double a,double b){return std::abs(a-b)<1e-10;}
std::vector<ValidationCheck> runValidationSuite(){SageParameters p{{{1,0},{0,1}},{{1,0},{0,1}},{0,0},{0,0},1};auto e=syntheticWavefront(4,3);auto r=sparseReconstruction(e,1,0);auto z=combinedLoss({1,2},{1,2},{true,false});return{{"mean aggregation exact",meanSageAggregate({{1,2},{3,4}})==Vector({2,3})},{"vertex update exact",graphSageUpdate({1,2},{{3,4},{5,6}},p)==Vector({5,7})},{"weighted LAT MSE",near(weightedLatMse({1,2},{0,0},{true,false}),3)},{"QRS duration",near(qrsDuration({4,9,1}),8)},{"combined zero loss",near(z.total,0)},{"anisotropy eigenvalues",near(anisotropyTensor({1,0,0})[0][0],1)&&near(anisotropyTensor({1,0,0})[1][1],1./3)},{"fiber virtual length",near(virtualEdgeLength({2,0,0},{1,0,0}),2)},{"transverse virtual length",near(virtualEdgeLength({0,3,0},{1,0,0}),std::sqrt(3.))},{"travel time",near(edgeTravelTime(6,3),2)},{"scar zero speed blocked",std::isinf(edgeTravelTime(1,0))},{"grid propagation",near(e.truth[3],3)&&near(e.truth[8],2)},{"full-sample demonstrator",r.mae<1e-12}};}
bool exportArtifacts(const std::filesystem::path& f,std::string* err){try{std::filesystem::create_directories(f);auto checks=runValidationSuite();int pass=std::count_if(checks.begin(),checks.end(),[](auto&x){return x.passed;});std::ofstream j(f/"validation_results.json");j<<"{\"Seed\":42,\"Passed\":"<<pass<<",\"Failed\":"<<checks.size()-pass<<",\"Total\":"<<checks.size()<<"}\n";auto e=syntheticWavefront();std::ofstream v(f/"reference_vectors.csv");v<<"vertex,x,y,truth\n";for(size_t i=0;i<e.truth.size();++i)v<<i+1<<','<<e.coordinates[i].first<<','<<e.coordinates[i].second<<','<<e.truth[i]<<'\n';std::ofstream b(f/"boundary_vectors.csv");b<<"case,input,result\nzero speed,\"l=1,c=0\",Infinity\nfiber aligned,\"e=(2,0,0)\",2\ntransverse,\"e=(0,3,0)\","<<std::setprecision(17)<<std::sqrt(3.)<<"\nempty neighborhood,dimension=2,\"{0,0}\"\n";std::ofstream s(f/"sampling_noise_sweep.csv");s<<"sampling_fraction,noise,mae\n";for(double q:{.1,.25,.5,.75,1.})for(double n:{0.,.25,1.})s<<q<<','<<n<<','<<sparseReconstruction(e,q,n).mae<<'\n';if(!j||!v||!b||!s)throw std::runtime_error("write failed");return true;}catch(const std::exception&x){if(err)*err=x.what();return false;}}
}
